`default_nettype none
`include "defines.sv"

// free input variables, can take any value each cycle as long as the `assume` are satisfied
module testbench (
	input check,
	input clock, reset
);
	`RVFI_WIRES
	`RVFI_BUS_WIRES

	`RISCV_FORMAL_CHECKER checker_inst (
		.clock  (clock),
		.reset  (reset),
		.check   (check),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

	// Ignore rvfi_order loopback, otherwise the check might be invalid.
	reg rvfi_order_loopback;
	always @(posedge clock) begin
		if (reset) begin
			rvfi_order_loopback <= 0;
		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
	reg h_past_valid;
	always @(posedge clock) begin
		h_past_valid <= 1'b1;
	end

	// rvfi_order is monotonically non-decreasing after reset.
	// Guard with $past(!reset) to avoid comparing against unknown cycle-0 state.
	always @(posedge clock) begin
		if (!reset && h_past_valid && $past(!reset)) begin
			h_order_non_decreasing: assert(rvfi_order >= $past(rvfi_order));
		end
	end

	// If a higher-order instruction has (ever) been observed that reads the selected
	// register, then found_non_causal may become sticky-high. With monotonically
	// increasing rvfi_order, it is impossible to later see rvfi_order == insn_order.
	// This blocks CTIs where found_non_causal is spuriously high when we bind
	// insn_order to the currently-retiring instruction.
	always @(posedge clock) begin
		if (!reset) begin
			h_no_time_travel: assert(!(rvfi_valid && (rvfi_order == checker_inst.insn_order) && checker_inst.found_non_causal));
		end
	end

/// Helper Assertion End
endmodule

