		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
	reg h_past_valid;
	always @(posedge clock) begin
		h_past_valid <= 1'b1;
	end

	// The DUT has an internal reset stretch (`reset_q`) that can stay high while
	// stalled. While it is high, RVFI outputs are forced to their reset values.
	always @(posedge clock) begin
		if (!reset) begin
			h_resetq_forces_rvfi: assert(!wrapper.uut.reset_q || ((rvfi_order == 0) && (rvfi_valid == 0)));
		end
	end

	// Once the internal reset is released, rvfi_order never decreases.
	always @(posedge clock) begin
		if (!reset && h_past_valid && $past(!reset) && !wrapper.uut.reset_q && !$past(wrapper.uut.reset_q)) begin
			h_order_non_decreasing: assert(rvfi_order >= $past(rvfi_order));
		end
	end

	// `found_non_causal` can become 1 only after observing some instruction with
	// order > insn_order that reads `register_index`. With monotonic rvfi_order,
	// that implies we've already advanced past insn_order.
	always @(posedge clock) begin
		if (!reset && !wrapper.uut.reset_q) begin
			h_found_implies_past_insn_order: assert(!checker_inst.found_non_causal || (rvfi_order > checker_inst.insn_order));
		end
	end

/// Helper Assertion End
endmodule

