		if (!reset) begin
			h_resetq_forces_rvfi: assert(!wrapper.uut.reset_q || ((rvfi_order == 0) && (rvfi_valid == 0)));
		end
	end

	// Track whether rvfi_order has wrapped (or otherwise decreased). We gate
	// order/insn_order reasoning on "no wrap observed".
	reg [63:0] h_prev_rvfi_order;
	reg h_prev_rvfi_order_valid;
	reg h_rvfi_order_wrapped;
	wire h_rvfi_order_wrap_now = h_prev_rvfi_order_valid && (rvfi_order < h_prev_rvfi_order);

	always @(posedge clock) begin
		if (reset) begin
			h_prev_rvfi_order <= 0;
			h_prev_rvfi_order_valid <= 0;
			h_rvfi_order_wrapped <= 0;
		end else begin
			h_prev_rvfi_order <= rvfi_order;
			h_prev_rvfi_order_valid <= 1;
			if (h_rvfi_order_wrap_now)
				h_rvfi_order_wrapped <= 1;
		end
	end

	// found_non_causal can only become 1 after observing an instruction with
	// rvfi_order > insn_order that uses register_index. Therefore, as long as
	// rvfi_order hasn't wrapped/decreased, found_non_causal implies we've already
	// advanced past insn_order.
	always @(posedge clock) begin
